package com.aryaa.sdm.service;
import com.aryaa.sdm.dto.*; import com.aryaa.sdm.model.*; import com.aryaa.sdm.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.util.stream.Collectors;
@Service @Transactional(readOnly=true)
public class StatsService {
 private final PatientRepository patients; private final HospitalRepository hospitals; private final RegionRepository regions; private final AlertLogRepository alerts;
 public StatsService(PatientRepository p,HospitalRepository h,RegionRepository r,AlertLogRepository a){patients=p;hospitals=h;regions=r;alerts=a;}
 public StatsDto getStats(){var ps=patients.findAll();var hs=hospitals.findAll();var rs=regions.findAll();var as=alerts.findAll();Map<Severity,Long> sev=new EnumMap<>(Severity.class);for(var s:Severity.values())sev.put(s,ps.stream().filter(p->p.getSeverity()==s).count());Map<PatientStatus,Long> st=new EnumMap<>(PatientStatus.class);for(var s:PatientStatus.values())st.put(s,ps.stream().filter(p->p.getStatus()==s).count());int total=hs.stream().mapToInt(Hospital::getTotalBeds).sum(),avail=hs.stream().mapToInt(Hospital::getBedsAvailable).sum();double occ=total==0?0:1.0-(double)avail/total;var ro=rs.stream().map(r->{var rh=hs.stream().filter(h->h.getRegion().getId().equals(r.getId())).toList();int t=rh.stream().mapToInt(Hospital::getTotalBeds).sum(),a=rh.stream().mapToInt(Hospital::getBedsAvailable).sum();return new RegionOccupancyDto(r.getName(),t,a);}).toList();Map<String,Long> abr=as.stream().collect(Collectors.groupingBy(AlertLog::getRegionName,Collectors.counting()));var recent=alerts.findTop10ByOrderByTriggeredAtDesc().stream().map(RecentAlertDto::from).toList();return new StatsDto(sev,st,total,avail,occ,ro,as.size(),abr,recent);}
}